import { canonicalDigest } from "@chainlesschain/context-memory-kernel";
import { createHash } from "node:crypto";
import { SESSION_GENERATION_AUTHORITY_FIELD } from "../harness/session-list-index.js";
import {
  encodePersistedMessage,
  decodeVerifiedPersistedMessage,
  getDurableSystemMessageProvenance,
  projectCanonicalResumeMessages,
} from "./session-message-provenance.js";

export const BRANCH_HISTORY_SCHEMA = "chainlesschain.session-branch-history/v1";
export const BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA =
  "chainlesschain.session-branch-history/v2";
export const BRANCH_HISTORY_MESSAGE = "session_history_message";
export const BRANCH_HISTORY_ORIGIN = "session_history_origin";
const capabilities = new WeakMap();

export const branchContextDigest = (messages) =>
  canonicalDigest(
    projectCanonicalResumeMessages(messages, { strict: true }).map(
      encodePersistedMessage,
    ),
    "chainlesschain.branch-history-context/v1",
  );
export const branchMessageDigest = (message) =>
  canonicalDigest(message, "chainlesschain.branch-history-message/v1");

// A caller cannot smuggle JSON-shaped history into a new authority chain. The
// capability exists only inside a verified source projection's synchronous lock.
export function withSessionBranchHistory(plan, task) {
  if (typeof task !== "function" || task.constructor?.name === "AsyncFunction")
    throw new TypeError("Branch history consumer must be synchronous");
  const capability = Object.freeze({});
  capabilities.set(capability, plan);
  try {
    const result = task(capability);
    if (result && typeof result.then === "function")
      throw new TypeError("Branch history consumer must be synchronous");
    return result;
  } finally {
    capabilities.delete(capability);
  }
}

export function resolveSessionBranchHistory(
  capability,
  parentSessionId,
  messages,
) {
  if (capability == null) return null;
  const plan = capabilities.get(capability);
  if (
    !plan ||
    plan.parentSessionId !== parentSessionId ||
    plan.contextDigest !== branchContextDigest(messages)
  ) {
    throw new Error(
      "Branch history capability is expired or does not match the branch",
    );
  }
  return plan;
}

export function createBranchHistoryImport() {
  let start = null;
  let index = 0;
  let active = null;
  const hash = (value) =>
    typeof value === "string" && /^[a-f0-9]{64}$/u.test(value);
  const integer = (value) => Number.isSafeInteger(value) && value >= 0;
  const invalid = () => {
    const error = new Error(
      "Branch display history is incomplete or inconsistent",
    );
    error.code = "SESSION_BRANCH_HISTORY_INVALID";
    throw error;
  };
  const require = (condition) => {
    if (!condition) invalid();
  };
  return {
    accept(event) {
      index += 1;
      if (index === 1 && event.type === "session_start") {
        const data = { ...event.data };
        delete data[SESSION_GENERATION_AUTHORITY_FIELD];
        start = { type: event.type, data };
      }
      if (event.type === "session_branch" && event.data?.history != null) {
        const descriptor = event.data.history;
        require(
          index === 2 &&
            start &&
            !active &&
            [
              BRANCH_HISTORY_SCHEMA,
              BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA,
            ].includes(descriptor.schema) &&
            hash(descriptor.sourceGeneration) &&
            integer(descriptor.totalMessages) &&
            integer(descriptor.contextMessageCount) &&
            descriptor.contextMessageCount <= 32768,
        );
        const coverage = descriptor.coverage;
        require(
          coverage?.kind === "from-origin"
            ? coverage.boundaryEvent === null && coverage.reason === null
            : coverage?.kind === "snapshot-boundary" &&
                hash(coverage.boundaryEvent) &&
                [
                  "timeline-replacement",
                  "context-snapshot",
                  "branch-snapshot",
                ].includes(coverage.reason),
        );
        const digest = createHash("sha256").update(
          `[${JSON.stringify(start)},${JSON.stringify({ type: event.type, data: event.data })}`,
        );
        active = {
          descriptor,
          digest,
          rows: 0,
          contexts: 0,
          pending: null,
          textParts: [],
          textBytes: 0,
          textIdentity: null,
          contextStarted: false,
        };
        return { kind: "start", coverage };
      }
      if (!active) {
        if (
          [BRANCH_HISTORY_MESSAGE, BRANCH_HISTORY_ORIGIN].includes(
            event.type,
          ) ||
          (event.type === "session_branch_complete" &&
            event.data?.schemaVersion === 2)
        )
          invalid();
        return null;
      }
      const state = active;
      if (event.type === "session_branch_complete") {
        require(
          !state.pending &&
            state.textParts.length === 0 &&
            state.rows === state.descriptor.totalMessages &&
            state.contexts === state.descriptor.contextMessageCount &&
            event.data?.schemaVersion === 2 &&
            event.data.messageCount === state.contexts &&
            event.data.inputDigest ===
              `sha256:${state.digest.update("]").digest("hex")}`,
        );
        active = null;
        return { kind: "complete" };
      }
      state.digest.update(
        `,${JSON.stringify({ type: event.type, data: event.data })}`,
      );
      if (event.type === BRANCH_HISTORY_MESSAGE) {
        const row = event.data;
        require(
          !state.contextStarted &&
            state.rows < state.descriptor.totalMessages &&
            ["user", "assistant", "tool"].includes(row?.role) &&
            typeof row.text === "string" &&
            row.text.length <= 128 * 1024 &&
            row.part === state.textParts.length &&
            typeof row.last === "boolean" &&
            hash(row.sourceEventId) &&
            integer(row.sourceItemIndex),
        );
        const identity = `${row.role}:${row.sourceEventId}:${row.sourceItemIndex}`;
        require(state.textIdentity === null || state.textIdentity === identity);
        state.textIdentity = identity;
        state.textBytes += Buffer.byteLength(row.text);
        require(
          state.textBytes <= 16 * 1024 * 1024 && state.textParts.length < 256,
        );
        state.textParts.push(row.text);
        if (!row.last) return { kind: "archive-part" };
        const message = { role: row.role, content: state.textParts.join("") };
        state.textParts = [];
        state.textBytes = 0;
        state.textIdentity = null;
        state.rows += 1;
        return { kind: "archive", message };
      }
      if (
        ["user_message", "assistant_message", "system"].includes(event.type)
      ) {
        require(
          !state.pending &&
            state.textParts.length === 0 &&
            state.rows === state.descriptor.totalMessages &&
            state.contexts < state.descriptor.contextMessageCount &&
            event.data?.role ===
              {
                user_message: "user",
                assistant_message: "assistant",
                system: "system",
              }[event.type],
        );
        state.contextStarted = true;
        state.pending = event.data;
        return { kind: "context" };
      }
      if (event.type === BRANCH_HISTORY_ORIGIN) {
        const message = state.pending;
        const origin = event.data?.origin;
        require(
          message && event.data.messageDigest === branchMessageDigest(message),
        );
        require(
          origin === null
            ? message.role === "system"
            : origin &&
                integer(origin.first) &&
                integer(origin.last) &&
                origin.first <= origin.last &&
                origin.last < state.rows &&
                (message.role !== "system" ||
                  (state.descriptor.schema ===
                    BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA &&
                    getDurableSystemMessageProvenance(
                      decodeVerifiedPersistedMessage(message),
                    ))),
        );
        state.contexts += 1;
        state.pending = null;
        return { kind: "origin", message, origin };
      }
      invalid();
    },
    finish() {
      if (active) invalid();
    },
  };
}

/**
 * Session branch planning (P0-3 "从这里分支" — the fourth restore action from
 * CLAUDE_CODE_IDE_INCREMENTAL_GAP_ANALYSIS_2026-07-13.md). Pure module: no RNG,
 * clock, fs or git — deterministic plans + lineage integrity checks.
 */
import { describe, it, expect } from "vitest";
import { TURN_COVERAGE, TurnBindingLog } from "../../src/lib/turn-binding.js";
import {
  deriveBranchId,
  deriveBranchSessionId,
  planSessionBranch,
  validateBranchLineage,
} from "../../src/lib/session-branch.js";

/** A FULL-coverage turn: mutated files WITH a checkpoint, no side-effects. */
function fullTurn() {
  const log = new TurnBindingLog();
  log.startTurn("turn-3", { conversationOffset: 3 });
  log.recordToolCall("turn-3", "tc-1", { name: "write_file" });
  log.bindCheckpoint("turn-3", "cp-abc");
  return log.get("turn-3");
}

describe("deriveBranchId", () => {
  it("is deterministic — same inputs hash to the same id", () => {
    expect(deriveBranchId("s1", "turn-3", 0)).toBe(
      deriveBranchId("s1", "turn-3", 0),
    );
  });
  it("disambiguates two branches off the SAME turn via seq", () => {
    expect(deriveBranchId("s1", "turn-3", 0)).not.toBe(
      deriveBranchId("s1", "turn-3", 1),
    );
  });
  it("differs by parent session and by turn", () => {
    expect(deriveBranchId("s1", "turn-3", 0)).not.toBe(
      deriveBranchId("s2", "turn-3", 0),
    );
    expect(deriveBranchId("s1", "turn-3", 0)).not.toBe(
      deriveBranchId("s1", "turn-4", 0),
    );
  });
});

describe("deriveBranchSessionId", () => {
  it("derives a traversal-safe id (no path separators survive)", () => {
    const id = deriveBranchSessionId("../evil/id", "ab/cd");
    expect(id).not.toContain("/");
    expect(id).not.toContain("\\");
    expect(id).toMatch(/^[A-Za-z0-9._~-]+$/);
  });
  it("embeds the parent and branch id", () => {
    expect(deriveBranchSessionId("s1", "deadbeef")).toBe("s1-b-deadbeef");
  });
});

describe("planSessionBranch", () => {
  it("targets a NEW session, preserves the parent, never inherits grants", () => {
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: fullTurn(),
    });
    expect(plan.branchSessionId).not.toBe("s1");
    expect(plan.branchSessionId).toContain("s1-b-");
    expect(plan.preservesParent).toBe(true);
    expect(plan.inheritSessionGrants).toBe(false);
    expect(plan.parentTurnId).toBe("turn-3");
    expect(plan.parentSessionId).toBe("s1");
  });

  it("keeps history up to the branch-point turn (truncate offset)", () => {
    const plan = planSessionBranch({ parentSessionId: "s1", turn: fullTurn() });
    expect(plan.conversationTruncateTo).toBe(3);
    expect(plan.fileCheckpointId).toBe("cp-abc");
    expect(plan.coverage).toBe(TURN_COVERAGE.FULL);
  });

  it("emits no warnings for a clean, read-only FULL branch point", () => {
    // FULL coverage AND no file mutation → nothing irreversible, no collision.
    const log = new TurnBindingLog();
    log.startTurn("turn-0", { conversationOffset: 0 });
    log.recordToolCall("turn-0", "r", { name: "read_file" });
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: log.get("turn-0"),
    });
    expect(plan.coverage).toBe(TURN_COVERAGE.FULL);
    expect(plan.requiresWorktree).toBe(false);
    expect(plan.warnings).toEqual([]);
  });

  it("requires a worktree when the branch intends to write", () => {
    const readOnlyLog = new TurnBindingLog();
    readOnlyLog.startTurn("turn-1", { conversationOffset: 1 });
    readOnlyLog.recordToolCall("turn-1", "tc", { name: "read_file" });
    const turn = readOnlyLog.get("turn-1");
    expect(turn.coverage).toBe(TURN_COVERAGE.FULL);

    const readPlan = planSessionBranch({ parentSessionId: "s1", turn });
    expect(readPlan.requiresWorktree).toBe(false);

    const writePlan = planSessionBranch({
      parentSessionId: "s1",
      turn,
      writeIntent: true,
    });
    expect(writePlan.requiresWorktree).toBe(true);
    expect(writePlan.warnings.join(" ")).toContain("isolated worktree");
  });

  it("requires a worktree when the branch point already mutated files", () => {
    // FULL turn that mutated files (has a checkpoint) → a divergent branch that
    // also writes would collide, so default to an isolated worktree.
    const plan = planSessionBranch({ parentSessionId: "s1", turn: fullTurn() });
    expect(plan.requiresWorktree).toBe(true);
  });

  it("warns honestly on PARTIAL coverage (irreversible side-effects)", () => {
    const log = new TurnBindingLog();
    log.startTurn("turn-2", { conversationOffset: 2 });
    log.recordToolCall("turn-2", "sh", { name: "run_shell" });
    log.bindCheckpoint("turn-2", "cp-x");
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: log.get("turn-2"),
    });
    expect(plan.coverage).toBe(TURN_COVERAGE.PARTIAL);
    expect(plan.warnings.join(" ")).toContain("irreversible side-effects");
  });

  it("warns when there is no file checkpoint (NONE coverage)", () => {
    const log = new TurnBindingLog();
    log.startTurn("turn-5", { conversationOffset: 5 });
    log.recordToolCall("turn-5", "ed", { name: "edit_file" }); // mutated, no checkpoint
    const turn = log.get("turn-5");
    expect(turn.coverage).toBe(TURN_COVERAGE.NONE);
    const plan = planSessionBranch({ parentSessionId: "s1", turn });
    expect(plan.warnings.join(" ")).toContain("no file checkpoint");
    expect(plan.requiresWorktree).toBe(true); // NONE = mutated files at point
  });

  it("warns and still preserves the parent on a missing conversation offset", () => {
    const log = new TurnBindingLog();
    log.startTurn("turn-9"); // no offset
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: log.get("turn-9"),
    });
    expect(plan.conversationTruncateTo).toBeNull();
    expect(plan.warnings.join(" ")).toContain("full parent history");
    expect(plan.preservesParent).toBe(true);
  });

  it("handles an unknown/absent turn without throwing", () => {
    const plan = planSessionBranch({ parentSessionId: "s1", turn: null });
    expect(plan.branchId).toBeNull();
    expect(plan.preservesParent).toBe(true);
    expect(plan.inheritSessionGrants).toBe(false);
    expect(plan.warnings.join(" ")).toContain("nothing to branch from");
  });

  it("honors an explicit branch session id", () => {
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: fullTurn(),
      branchSessionId: "my-branch",
    });
    expect(plan.branchSessionId).toBe("my-branch");
  });
});

describe("validateBranchLineage", () => {
  it("accepts a clean tree (root + children)", () => {
    const res = validateBranchLineage([
      { sessionId: "root", parentSessionId: null },
      { sessionId: "b1", parentSessionId: "root" },
      { sessionId: "b2", parentSessionId: "b1" },
    ]);
    expect(res.ok).toBe(true);
    expect(res.cycles).toEqual([]);
    expect(res.orphans).toEqual([]);
  });

  it("flags an orphan (parent not present)", () => {
    const res = validateBranchLineage([
      { sessionId: "b1", parentSessionId: "ghost" },
    ]);
    expect(res.ok).toBe(false);
    expect(res.orphans).toContain("b1");
  });

  it("detects a cycle — a branch cannot be its own ancestor", () => {
    const res = validateBranchLineage([
      { sessionId: "a", parentSessionId: "b" },
      { sessionId: "b", parentSessionId: "a" },
    ]);
    expect(res.ok).toBe(false);
    expect(res.cycles.length).toBe(1);
    expect(res.cycles[0].sort()).toEqual(["a", "b"]);
  });

  it("ignores malformed records", () => {
    const res = validateBranchLineage([null, { parentSessionId: "x" }, 42]);
    expect(res.ok).toBe(true);
  });
});

import { afterAll, describe, expect, it, vi } from "vitest";
import {
  appendFileSync,
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { Command } from "commander";
import { ContextMemoryKernel } from "@chainlesschain/context-memory-kernel";

const root = mkdtempSync(join(tmpdir(), "cc-history-"));
vi.mock("../../src/lib/paths.js", () => ({
  getHomeDir: () => join(root, "home"),
  getClaudeProjectStorageDir: () => null,
  getStatePath: () => join(root, "home", "state"),
  getMachineSecurityAnchorDir: () => join(root, "security"),
}));
const store = await import("../../src/harness/jsonl-session-store.js");
const {
  readSessionTranscriptHistory,
  createSessionTranscriptHistoryProjection,
  createSessionTranscriptBranchProjection,
} = await import("../../src/lib/session-transcript-history.js");
const { readSessionTranscriptPage } =
  await import("../../src/lib/session-transcript-page.js");
const { JsonlSessionContextPort } =
  await import("../../src/lib/context-memory-kernel/jsonl-session-context-port.js");
const { createSummaryContextItem } =
  await import("../../src/lib/context-memory-kernel/message-adapter.js");
const { HISTORY_PREFIX_SCHEMA } =
  await import("../../src/lib/session-history-origins.js");
const { HISTORY_SUMMARY_SCHEMA, projectCheckpointSummary } =
  await import("../../src/lib/checkpoint-summary-projection.js");
const { branchMessageDigest } =
  await import("../../src/lib/session-branch-history.js");
const { registerSessionShowSubcommand } =
  await import("../../src/commands/session-show.js");
const { parseTranscriptPage } =
  await import("../../../vscode-extension/src/chat/transcript-cache.js");

afterAll(() => rmSync(root, { recursive: true, force: true }));

async function compact(sessionId, operationId, options = {}) {
  const kernel = new ContextMemoryKernel({
    sessionPort: new JsonlSessionContextPort({ sessionId }),
  });
  const result = await kernel.compactContext({
    operationId,
    sessionId,
    modelWindowTokens: 150,
    reservedOutputTokens: 20,
    safetyMarginTokens: 10,
    recoveryReserveTokens: 10,
    sink: "provider.local",
    scopeAdmissions: [{ scope: "session", scopeId: sessionId }],
    policyVersion: "test",
    modelProfile: "test",
    now: "2026-09-27T00:00:00.000Z",
    ...options,
  });
  expect(result.status).toBe("committed");
}
function start(id, count = 8) {
  store.startSession(id, { provider: "test", model: "test" });
  for (let i = 0; i < count; i++) {
    store.appendUserMessage(id, `question-${i}: ${"x".repeat(90)}`);
    store.appendAssistantMessage(id, `answer-${i}: ${"y".repeat(90)}`);
  }
}
function texts(page) {
  return page.messages.map((m) => m.text);
}
function rewriteCursor(cursor, patch) {
  return Buffer.from(
    JSON.stringify({
      ...JSON.parse(Buffer.from(cursor, "base64url").toString("utf8")),
      ...patch,
    }),
  ).toString("base64url");
}
function rewind(id, retainedMessageCount, patch = {}) {
  const messages = store.readVerifiedMessages(id);
  const head = store.findLatestEvent(id, null).hash;
  return store.withSessionAuthorityTransaction(id, head, (transaction) =>
    transaction.appendAuthorityEvent("checkpoint_timeline_commit", {
      action: "restore-conversation",
      messages: messages.slice(0, retainedMessageCount),
      historyPrefix: {
        schema: HISTORY_PREFIX_SCHEMA,
        sourceHead: transaction.currentHeadHash(),
        sourceMessageCount: messages.length,
        retainedMessageCount,
        ...patch,
      },
      binding: { turns: [] },
    }),
  );
}
function summarize(id, action, start, end, change = () => {}) {
  const messages = store.readVerifiedMessages(id);
  end ??= messages.length;
  const head = store.findLatestEvent(id, null).hash;
  return store.withSessionAuthorityTransaction(id, head, (transaction) => {
    const data = {
      action,
      turnId: "selected",
      messages: projectCheckpointSummary({
        messages,
        action,
        start,
        end,
        turnId: "selected",
      }).map(({ message }) => message),
      historySummary: {
        schema: HISTORY_SUMMARY_SCHEMA,
        sourceHead: transaction.currentHeadHash(),
        sourceMessageCount: messages.length,
        start,
        end,
      },
      binding: { turns: [] },
    };
    change(data);
    return transaction.appendAuthorityEvent("checkpoint_timeline_commit", data);
  });
}
function historyBranch(parentSessionId, branchSessionId, retainedMessageCount) {
  const messages = store
    .readVerifiedMessages(parentSessionId)
    .slice(0, retainedMessageCount);
  const head = store.findLatestEvent(parentSessionId, null).hash;
  return store.withSessionAuthorityTransaction(
    parentSessionId,
    head,
    (transaction) =>
      transaction.readProjection(() =>
        createSessionTranscriptBranchProjection(
          parentSessionId,
          messages,
          (history) =>
            store.createBranchSession({
              parentSessionId,
              branchSessionId,
              parentTurnId: "selected",
              messages,
              history,
            }),
        ),
      ),
  );
}

